begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
grant analysis_writer to postgres with set true;
grant usage on schema extensions to analysis_writer;
insert into auth.users(id,is_anonymous) values('ea100000-0000-4000-8000-000000000001',true),('ea100000-0000-4000-8000-000000000002',true),('ea100000-0000-4000-8000-000000000003',false);
insert into public.organizations(id,name) values('ea200000-0000-4000-8000-000000000001','Complete A'),('ea200000-0000-4000-8000-000000000002','Complete B');
insert into public.stores(id,org_id,name) values('ea300000-0000-4000-8000-000000000001','ea200000-0000-4000-8000-000000000001','Complete A'),('ea300000-0000-4000-8000-000000000002','ea200000-0000-4000-8000-000000000002','Complete B');
insert into public.devices(id,org_id,store_id,auth_user_id,label) values('ea400000-0000-4000-8000-000000000001','ea200000-0000-4000-8000-000000000001','ea300000-0000-4000-8000-000000000001','ea100000-0000-4000-8000-000000000001','A'),('ea400000-0000-4000-8000-000000000002','ea200000-0000-4000-8000-000000000002','ea300000-0000-4000-8000-000000000002','ea100000-0000-4000-8000-000000000002','B');
insert into public.memberships(org_id,user_id,role) values('ea200000-0000-4000-8000-000000000001','ea100000-0000-4000-8000-000000000003','owner');
create temporary table complete_context(key text primary key,value text);
grant all on complete_context to authenticated,analysis_writer,anon;
create function pg_temp.sid() returns uuid language sql as $$select value::uuid from complete_context where key='session'$$;
create function pg_temp.rid() returns uuid language sql as $$select value::uuid from complete_context where key='request'$$;
create function pg_temp.pid() returns uuid language sql as $$select value::uuid from complete_context where key='plan'$$;
create function pg_temp.beauty(p_patch jsonb default '{}'::jsonb) returns jsonb language sql as $$select jsonb_build_object('request_id',pg_temp.rid(),'mode','openai_beauty','model_version','gpt-4.1-mini-2025-04-14','prompt_version','beauty-style-suggestion-v2','image_quality','usable','undertone','cool','chroma','soft','face_shape','oval','eye_shape','almond','nose_shape','medium','lip_fullness','medium','quality_flags','[]'::jsonb)||p_patch$$;
create function pg_temp.skin(p_patch jsonb default '{}'::jsonb) returns jsonb language sql as $$select '{"prompt_version":"visible-appearance-eval-v1","image_quality":"usable","quality_flags":[],"observed_features":{"visible_redness":"uncertain","visible_spots":"not_visible","visible_pores":"visible","visible_fine_lines":"not_visible","visible_flaking":"not_visible"}}'::jsonb||p_patch$$;
create function pg_temp.prefs(p_mood text default 'fresh') returns jsonb language sql as $$select jsonb_build_object('paletteId','cool_soft','faceShape','oval','hairLength','any','mood',p_mood,'finish','any')$$;
select is((select count(*)::integer from pg_tables where schemaname='public' and tablename like 'session_complete_%' and rowsecurity),10,'All ten transient complete relations enable RLS');
select ok(not has_table_privilege('authenticated','public.session_complete_guest_context','SELECT,INSERT,UPDATE,DELETE'),'Guest context is exposed through owned bounded RPCs only');
select ok(not has_table_privilege('service_role','public.store_weekly_beauty_demographics','SELECT,INSERT,UPDATE,DELETE'),'No service-role demographics table access');
select is((select count(*)::integer from information_schema.columns where table_schema='public' and table_name like 'session_complete_%' and column_name in ('gender','animal_vibe','landmarks','photo','prompt','image','base_depth_suggestion')),0,'No individual Gender, images or ephemeral photo inferences in transient tables');
select ok(not has_function_privilege('authenticated','public.write_openai_complete_analysis(uuid,uuid,jsonb,jsonb)','EXECUTE'),'Guest cannot forge combined observations');
select ok(not has_function_privilege('analysis_writer','public.kiosk_claim_complete_analysis(uuid)','EXECUTE'),'Writer cannot manufacture consent or claims');
select ok(not has_table_privilege('anon','public.complete_beauty_saved_guides','SELECT'),'Phone capability has no base-table access');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ea100000-0000-4000-8000-000000000001","is_anonymous":true}',true);
insert into complete_context values('session',public.start_kiosk_session()::text);
select lives_ok($$select public.kiosk_set_beauty_guest_context(pg_temp.sid(),'under13','ko',false)$$,'Under13 can be screened without collecting a photo');
select public.record_consent(pg_temp.sid(),'2026-10-openai-v1',true);
select throws_ok($$select public.kiosk_set_complete_photo_consent(pg_temp.sid(),true,'2026-10-beauty-complete-photo-v1')$$,'42501',null,'Under13 photo prohibited');
select throws_ok($$select public.kiosk_set_beauty_guest_context(pg_temp.sid(),'16-17','ko',true)$$,'22023',null,'Teen analytics prohibited');
select public.kiosk_set_beauty_guest_context(pg_temp.sid(),'16-17','ko',false);
select throws_ok($$select public.kiosk_set_complete_photo_consent(pg_temp.sid(),true,'2026-10-beauty-complete-photo-v1')$$,'42501',null,'Teen photo release defaults off');
select public.kiosk_set_beauty_guest_context(pg_temp.sid(),'25-34','ko',true);
select throws_ok($$select public.kiosk_set_complete_photo_consent(pg_temp.sid(),true,'2026-10-beauty-photo-v1')$$,'22023',null,'Legacy purpose cannot grant integrated transmission');
select public.kiosk_set_complete_photo_consent(pg_temp.sid(),true,'2026-10-beauty-complete-photo-v1');
insert into complete_context values('request',public.kiosk_claim_complete_analysis(pg_temp.sid())::text);
select throws_ok($$select public.kiosk_claim_complete_analysis(pg_temp.sid())$$,'23505',null,'Single durable combined attempt');
select public.record_beauty_consent(pg_temp.sid(),'2026-10-beauty-photo-v1',true);
select throws_ok($$select public.claim_kiosk_beauty_analysis(pg_temp.sid())$$,'42501',null,'Legacy purpose cannot add a second external attempt to integrated flow');
select is(public.read_kiosk_beauty_complete(pg_temp.sid())->'guest'->>'locale','ko','Read state preserves selected locale');
select set_config('request.jwt.claims','{"sub":"ea100000-0000-4000-8000-000000000002","is_anonymous":true}',true);
select throws_ok($$select public.read_kiosk_beauty_complete(pg_temp.sid())$$,'42501',null,'Cross-tenant device cannot read integrated context');
reset role;
set local role analysis_writer;
select throws_ok($$select public.write_openai_complete_analysis(pg_temp.sid(),pg_temp.rid(),pg_temp.beauty()||'{"animal_vibe":"cat"}',pg_temp.skin())$$,'22023',null,'Ephemeral animal cannot enter persisted beauty result');
select throws_ok($$select public.write_openai_complete_analysis(pg_temp.sid(),pg_temp.rid(),pg_temp.beauty(),pg_temp.skin('{"image_quality":"not_assessable","quality_flags":["no_face"]}'))$$,'22023',null,'Invalid skin quality block rejected atomically');
select lives_ok($$select public.write_openai_complete_analysis(pg_temp.sid(),pg_temp.rid(),pg_temp.beauty(),pg_temp.skin())$$,'Restricted writer saves bounded normalized beauty and skin atomically');
reset role;
select is((select count(*)::integer from public.analysis_vision_features where org_id='ea200000-0000-4000-8000-000000000001'),5,'Exactly five normalized skin features');
select ok((select answers_completed_at is null and skin_sensitive is null and skin_type_id is null from public.kiosk_sessions where id=pg_temp.sid()),'Integrated analysis never fabricates legacy answers');
select is((select sessions_analyzed from public.store_daily_metrics where org_id='ea200000-0000-4000-8000-000000000001' and day=(now() at time zone 'UTC')::date),1,'Combined photo counts one analysis session');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ea100000-0000-4000-8000-000000000001","is_anonymous":true}',true);
select public.confirm_complete_beauty_preferences(pg_temp.sid(),pg_temp.prefs());
select public.kiosk_set_complete_base_choice(pg_temp.sid(),'medium','cool','match');
select throws_ok($$select public.kiosk_create_preview_plan(pg_temp.sid())$$,'42501',null,'Preview purpose starts unticked');
select public.kiosk_set_complete_preview_consent(pg_temp.sid(),true,'2026-10-beauty-preview-v1');
insert into complete_context values('plan',public.kiosk_create_preview_plan(pg_temp.sid())->>'id');
reset role;
update public.kiosk_sessions set started_at=now()-interval '10 minutes' where id=pg_temp.sid();
update public.session_complete_preview_plans set deadline=now()+interval '12 minutes' where session_id=pg_temp.sid();
-- Recreate through the actual insert boundary without changing active slot data.
delete from public.session_complete_preview_plans where session_id=pg_temp.sid();
set local role authenticated;
update complete_context set value=public.kiosk_create_preview_plan(pg_temp.sid())->>'id' where key='plan';
reset role;
select ok((select p.deadline<=s.started_at+interval '15 minutes' from public.session_complete_preview_plans p join public.kiosk_sessions s on s.org_id=p.org_id and s.id=p.session_id where s.id=pg_temp.sid()),'Preview deadline bounded by remaining absolute session lifetime');
set local role authenticated;
select is(jsonb_array_length(public.read_kiosk_beauty_complete(pg_temp.sid())->'previewPlan'->'slots'),9,'Exactly nine slots');
select throws_ok($$select public.kiosk_claim_preview_slot(pg_temp.sid(),pg_temp.pid(),3)$$,'22023',null,'Cannot skip makeup slots');
select lives_ok($$select public.kiosk_claim_preview_slot(pg_temp.sid(),pg_temp.pid(),0)$$,'First slot claims one request');
reset role;
update public.session_complete_preview_slots set claimed_at=now()-interval '74 seconds' where plan_id=pg_temp.pid() and slot=0;
set local role authenticated;
select lives_ok($$select public.kiosk_assert_preview_slot(pg_temp.sid(),pg_temp.pid(),0)$$,'Integrated preview is admitted within its75second HTTP window');
reset role;
update public.session_complete_preview_slots set claimed_at=now()-interval '76 seconds' where plan_id=pg_temp.pid() and slot=0;
set local role authenticated;
select throws_ok($$select public.kiosk_assert_preview_slot(pg_temp.sid(),pg_temp.pid(),0)$$,'42501',null,'Integrated preview rejects a result after its75second attempt ceiling');
reset role;
update public.session_complete_preview_slots set claimed_at=now() where plan_id=pg_temp.pid() and slot=0;
set local role authenticated;
select throws_ok($$select public.kiosk_claim_preview_slot(pg_temp.sid(),pg_temp.pid(),0)$$,'23505',null,'Cannot repeat a charged slot');
select public.kiosk_complete_preview_slot(pg_temp.sid(),pg_temp.pid(),0,'failed');
select lives_ok($$select public.kiosk_claim_preview_slot(pg_temp.sid(),pg_temp.pid(),1)$$,'Failed slot permits next slot without retry');
select public.confirm_complete_beauty_preferences(pg_temp.sid(),pg_temp.prefs('defined'));
select throws_ok($$select public.kiosk_assert_preview_slot(pg_temp.sid(),pg_temp.pid(),1)$$,'42501',null,'Changed direction rejects in-flight result');
select public.kiosk_set_complete_skin_profile(pg_temp.sid(),'unsure',array['texture'],array[]::text[]);
select is(public.read_kiosk_beauty_complete(pg_temp.sid())->'skinProfile'->>'skinType','unsure','Unknown skin type remains unknown');
select lives_ok($$select public.create_complete_beauty_guide(pg_temp.sid(),repeat('a',64),'2026-10-complete-save-v1',array[]::uuid[])$$,'Opt-in guide pins confirmed choices with empty eligible catalog');
select public.finish_kiosk_beauty_complete(pg_temp.sid(),'woman');
select lives_ok($$select public.finish_kiosk_beauty_complete(pg_temp.sid(),'woman')$$,'Finish idempotent');
reset role;
select is((select completed_sessions from public.store_weekly_beauty_demographics where org_id='ea200000-0000-4000-8000-000000000001' and dimension='age'),1,'Adult opted-in age counted once');
select is((select completed_sessions from public.store_weekly_beauty_demographics where org_id='ea200000-0000-4000-8000-000000000001' and dimension='gender'),1,'Ephemeral Gender contributes only to aggregate');
select is((select count(*)::integer from public.session_complete_guest_context where session_id=pg_temp.sid()),0,'Finish purges age and locale context');
select is((select count(*)::integer from public.session_complete_preview_plans where session_id=pg_temp.sid()),0,'Finish purges generation metadata and slots');
select is((select count(*)::integer from public.session_complete_saved_guides where session_id=pg_temp.sid()),0,'Finish removes session-to-capability linkage');
set local role anon;
select is(public.read_complete_beauty_guide(repeat('a',64))->>'locale','ko','Cookie-free capability survives Finish and preserves locale');
select ok(public.read_complete_beauty_guide(repeat('a',64)) ? 'preferences','Capability includes confirmed guide');
select ok(not(public.read_complete_beauty_guide(repeat('a',64)) ?| array['guest','gender','skinVision','animalVibe','ratios','image']),'Capability excludes appearance and demographic data');
select public.revoke_complete_beauty_guide(repeat('a',64));
select is(public.read_complete_beauty_guide(repeat('a',64)),null::jsonb,'Phone revoke immediately removes capability');
reset role;
update public.store_weekly_beauty_demographics set week_start=(date_trunc('week',now() at time zone 'UTC')::date-7) where org_id='ea200000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ea100000-0000-4000-8000-000000000003","is_anonymous":false}',true);
select is(public.read_staff_beauty_demographics('ea300000-0000-4000-8000-000000000001')->'age'->>'suppressed','true','Small nonzero age cell suppresses entire dimension');
select is(public.read_staff_beauty_demographics('ea300000-0000-4000-8000-000000000001')->'gender'->'counts','{}'::jsonb,'No subtraction leakage from suppressed distribution');
select throws_ok($$select public.read_staff_beauty_demographics('ea300000-0000-4000-8000-000000000002')$$,'42501',null,'Staff cannot read another tenant demographics');
reset role;
update public.store_weekly_beauty_demographics set completed_sessions=10 where org_id='ea200000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ea100000-0000-4000-8000-000000000003","is_anonymous":false}',true);
select is(public.read_staff_beauty_demographics('ea300000-0000-4000-8000-000000000001')->'age'->'counts'->>'25-34','10','Threshold distribution exposed as completed sessions');
select set_config('request.jwt.claims','{"sub":"ea100000-0000-4000-8000-000000000001","is_anonymous":true}',true);
update complete_context set value=public.start_kiosk_session()::text where key='session';
select public.kiosk_set_beauty_guest_context(pg_temp.sid(),'25-34','en',true);
select public.record_consent(pg_temp.sid(),'2026-10-openai-v1',true);
select public.confirm_complete_beauty_preferences(pg_temp.sid(),pg_temp.prefs());
reset role;
update public.kiosk_sessions set started_at=now()-interval '16 minutes',last_activity_at=now() where id=pg_temp.sid();
set local role authenticated;
select throws_ok($$select public.read_kiosk_beauty_complete(pg_temp.sid())$$,'42501',null,'Recent activity cannot extend absolute photo session expiry');
select lives_ok($$select public.finish_kiosk_beauty_complete(pg_temp.sid(),'woman')$$,'Finish cleans an absolute expired session');
reset role;
select is((select status from public.kiosk_sessions where id=pg_temp.sid()),'expired','Expired finish does not convert into completed session');
select is((select sum(completed_sessions)::integer from public.store_weekly_beauty_demographics where org_id='ea200000-0000-4000-8000-000000000001' and dimension='age'),10,'Expired finish contributes no new demographic count');
reset role;
select * from finish();
rollback;
